) AS (
  VALUES 
    (487::BIGINT, 'De las mejores profes que he tenido. Explica súper claro y es muy amable. Utiliza Khan Academy lo cual ayuda mucho a estudiar y los quices suelen ser en pareja o los deja para la casa. Si pudiera llevar todas las mates con ella, lo haría sin duda'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-07T00:00:00+00:00'::TIMESTAMPTZ, '9d101fdc22c950ae7ef95a2a64ded5bf5860fb416f605cd4c663f5c34bea561e'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Excelente profesora, si pudiera llevar los otros cálculos con ella lo haría, explica excelente y las veces que uno necesite, fui varias veces a consulta con ella y es demasiado dulce. Los quices se pueden hacer en parejas y hace bastantes ejercicios en clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'abad43f1ac6945cef7872f0f06ff53659459a17cf4d58c0332484b2f6e3de9b7'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es muy buena para explicar, un pan de Dios. Te ayuda mucho y, si le pides que explique otra vez, lo hace sin ningún problema. Explica de una manera muy detallada y sencilla, prácticamente paso a paso. El único inconveniente es que va bastante despacio, por lo que la materia puede acumularse'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'bd55ead463817dcff60225d5b28e3f26f5bd12b280b11ed442e17f21d4729025'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Amigo o amiga, no, con ella no, sus explicaciones son confusas suele calificar de manera muy ruda y hace mucho enredo mental, mejor busca otra opcion y salva tu alma.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-05-19T00:00:00+00:00'::TIMESTAMPTZ, '49368ee8406c09a89afc728c46512d3ba82caadbc4c1be35f87121fdafef2801'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2026-03-24T00:00:00+00:00'::TIMESTAMPTZ, '2fdf522813e7411fedb414be39d144150e1a1084917d1d67a4e477a4e3649101'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profesora, es muy clara para explicar y si es necesario puedes preguntarle mil veces y ella te explica. El curso es difícil pero con ella se vuelve llevadero, es muy flexible y aparte una persona muy especial'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'd57d2cc3d7f5c2410ca45a22a18ccbf0225720fb528ebf899e4ebb0374ae3d6a'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Amigos no, si lo lleva pro primera vez, ella no es su mejor opción. Muy buena para MG, muy dura para CDI, su forma de evaluar es compleja y si no hacés las cosas como las explicó en clase sepa que ni un punto le va a dar.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '5070e0c266266491d9e534838143f9c6afdfb8fcbd22a3cdb5e782ddf7434bd7'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'La mejor de la escuela de mate, no dude en matricular con ella. Sus clases son muy claras y entretenidas, los quices van acorde con la materia y califica de una manera justa. También es muy amable y excelente como persona'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-19T00:00:00+00:00'::TIMESTAMPTZ, '76c6d437a45bc5301cefd08780145b6d1b3566ed05a7cd1f067cdd71e6d77775'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es increiblemente buena profesora. Todas las clases estaban bien organizadas y da la materia con total claridad. Enseña muy bien y si uno le presta atención es muy fácil. Hace mucho quiz o ejercicios pero entra poquito y se va ganando nota fácilmente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-09T00:00:00+00:00'::TIMESTAMPTZ, '4418530656272a4286e8390458fe6006f0ed90965565f7b8b93c74ff8302d0f9'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'La mejor profe de la Escuela de Matemáticas. Explica súper bien desde. Siempre inicia los temas nuevos con una breve demostración, facilitando el análisis de los ejercicios posteriores (y en los exámenes). No se enreda, prepara la clase del día, en las evaluaciones quita cada 0.25 puntos, etc'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, '1224a676b68289e924134e70451ab7c6cb4e802df6365ba74f2884a2e484d3f2'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Lo llevé por primera vez con ella y te digo que no es mi tipo de profesora. Me parece que es muy dura al calificar. La mayoría del grupo que pasó fue porque lo llevaban por segunda o tercera vez. Los Khan ayudan, los quizzes a veces son en parejas, pero en los exámenes, si hacés algo con otro método'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4d827c053290270ac9374bcff1c8befa38dbef4308b9369675630f43acf97ac9'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es una excelente profe, trate de ir a consulta porque le va a ayudar muchísimo. En los quices a veces se acumula un poco la materia, pero si lleva todo al día le va a ir súper bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '4446f3b96a7ed984480e0380b202cfc500795c7a726b5700517d097fa8c40d1e'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Es mi mamá. La adoro como persona y como profe más, super clara, pasa preguntando por dudas respecto a la materia, le da muchas bases para lineal, practique y vaya a consulta, y pasa con 90'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '0e369fd0ac15714bc9a982bdbd41a8350c468b55b241208b942754e5ddfad6d5'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es un sol, explica bien, si practica, los quices son fáciles, es muy amable a la hora de resolver dudas y es una mente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-21T00:00:00+00:00'::TIMESTAMPTZ, '92e39f402e9f5a21d74d6a945aec887e96fc21bbc3c4aefc4f1eb0e4b48516a4'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Muy clara con sus evaluaciones, explica bien. La profe es un amor, no es nada grosera, solo compórtese como una persona adulta (no hable mientras ella explica).'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2024-12-27T00:00:00+00:00'::TIMESTAMPTZ, '3b01b0a105f257388770cb6c1e52ed30dfec2551a5b1c1784c15045201cb18ae'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profe, explica muy bien pero hay muchos quices y explica muy rapido, si presta atencion pasa bien.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos exámenes']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '2df3e3a46997b7a2d9c2531c505e128591c1fcc861627a2b06371ba40d79e0c4'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Lourdes es el ejemplo de una profesora muy muy muy buena enseñando, pero a la vez es muy muy muy brutal calificando. Pasarlo con ella no es imposible, y por como llegue al curso se me hizo duro, pero si va a matricular con ella, póngale, porque usted entenderá, pero calificará muy duro.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '5dcb1c8feac4cbeaa2c7c9da7df1b8488d5ba56a6b61d138ca80a48e2949ce6c'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es muy buena profe y como persona también. Recomiendo ir a horas consulta, es muy amable y atiende todas sus dudas. Los quices son duros, puede decir que más que los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd9392707af22e3895f693c643823a34dc6e3857b58ae5764045f246ab94b0ed0'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'No es mala profe del todo pero si tiene que saber cosas desde antes.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '003eecf380a1851061df57613c88356b0fda221aafaef395457144418be2d047'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'la profeexplica como si fueramos todos genios, es muy desordenada y hace quizes que no tienen nada que ver con los ejercicios que hizo ella en clase. ademas retrasa mucho los quizes cuanodo le da la gana y mete materia recien vista en clase'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4331d04563b23911ab116f97167df8ce2df8649c163172276d1264f6c03993e8'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'clase confusa, hace quizes difíciles y enreda más'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '9bbfcf83b29ea3a634638f7e6ce3ec9ddcf717cd01f628f70b98f6b60644f985'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Muy buena profe, explica bien y da muchos ejemplos de cada tema, aclara dudas en clase y sino entonces se puede ir a consulta. Para pasar el curso es muy importante ir haciendo las prácticas semanales de cátedra para que pueda aclarar sus dudas con la profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'dff825bd863b29ba7f52981358642eaf8a299e5de406d1e08a5dfdfa5d168607'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'La profe es muy amable, los quices son acordes a lo visto en clase (son largos), los exámenes los califica justamente'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '43a1fc4d6b11cf88d98a8af0f0a90023f251cdeff5d1e3c93cee19dceb00f8eb'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Pesima, la señora explica por encima, con que 2 entiendan está bien para ella, es super arrogante y si usted la contradice se le va encima. Los ejercicios son super diferentes a los de los examenes, 0 recomendada, los quices son un asco y califica como si uno fuera el profesor de matematica'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'fb3e008f29d88e87d8d1d608be75c6e213db9300d42bd01f3bd0f548dbed5f80'::TEXT, ARRAY[563, 2439]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-05-28T00:00:00+00:00'::TIMESTAMPTZ, '601862f55441916d1bbb83511fb5e938dd3e572104678ad23aa48624ab38786a'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'af6d5d0d37f42c02c5de289cc6fd726a547776eacb1fbc8f9f5c139c9f417bb8'::TEXT, ARRAY[563, 2439]::BIGINT[]),
    (487::BIGINT, 'La profesora es excelente, explica muy bien y da varios ejemplos, recomendada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-12-14T00:00:00+00:00'::TIMESTAMPTZ, '1641a83b7b6b3ce1bac72d59ceb051d4a41b4678fc4ec711bf6d3a44e8199f6c'::TEXT, ARRAY[2439]::BIGINT[]),
    (487::BIGINT, 'Muy buena profe. El curso es un poco rudo, pero ella explica bastante claro con PPT y ejercicios variados; sin embargo, SIEMPRE se debe estudiar de práctica de cátedra para los exámenes. Dispuesta a atender dudas dentro y fuera de clase. Hace varios quices normalmente en parejas. Recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '41faa6fcaabe4f21966dc9a3ef732fc9ac9993129630aa5fd0bce20bdd4e30f3'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es muy buena profesora, explica muy bien y se le entiende claro. Da ejemplos fuertes los cuales sirven para estudiar, si puede matricule con un amig@ que sea bueno para que haga los quices con esta persona y no depender de ningún mon0'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '27b8bd2131a0bc1801c279a2ecd8fcc62ebbd68f42d10ab260c8f96bf997b008'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Explica muy bien la materia. Solo da un ejemplo de cada cosa. Los quices son dificilillos y no perdona puntos. Pero es súper buena persona y muy atenta a cualquier duda. Dura un poco calificando exámenes porque suele dar el grupo de 70 personas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '91527744414fbaa1f568b05f2d559bb8d162e50e5ba05ad65c67168953e3b5d5'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es una profe muy dulce y se aprende mucho con ella. Hace quices en pareja, aunque califica duro, pero da buena retroalimentación y es muy paciente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '61289a296e3eb2aea1975ed622d5ef2fcbd92caf7268ffa8de232082dbd97212'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Una profe excelente, sabe mucho de la materia y la explica con mucha claridad, las clases son para 70 personas sin embargo siempre está atenta a dudas. Califica duro pero da una retroalimentación buena. Los quices fueron en pareja la mayoría o virtuales. Si tiene la oportunidad matricule con ella'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '774d5a41d1d88cd9225eacdc3b4f51847b7a8c04ba1e09df591548d2c9e7ab8a'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es mi mamá, la amo. Es increíble profesora y ayuda un montónnn, es súper tranqui repasando cosas de mate elemental. Lo único que son clases de 75 personas y hace muchos quizzes, pero la mayoría en parejas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2023-11-13T00:00:00+00:00'::TIMESTAMPTZ, '93af6684042eda360ac2798dd4ea62a3fefd654c37b0506b1530fc54f202b1e2'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'b0afd49e233ca4f4a248fecb8c0ff97e30f11c8c9fbf2630a519266c98739ff2'::TEXT, ARRAY[563, 2439]::BIGINT[]),
    (487::BIGINT, 'Una profe súper linda, muy comprensible y de verdad está atenta en todo momento por si usted tiene alguna duda. Explica de forma muy clara y siempre es muy paciente y respetuosa. Las clases son un poco pesadas pero es más que todo por el curso. Los quices son una gran práctica para los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'eb4c60e136012d05cc02d937cd439a72c176301c9b609c2bf2ac1d5969297ba2'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'La profe es muy buena gente, explica muy bien, pero aveces vas muuy rapido entonces uno se pierde. Pasaba diciendo que "ibamos atrasados con la materia" entonces explicaba más rapido. Sin embargo eso es mas problema del curso que de la profe. Lourdes es muy dulce y paciente, aproveche consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2022-12-10T00:00:00+00:00'::TIMESTAMPTZ, '3a5d1fbea59364e6e0a0ce396cb9cc38541412a7689756fd127e890af448b1cd'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Legalmente CDI es un curso difícil y pesado, si usted no tiene unas bases matemáticas buenas, le deseo suerte, pero pese a eso Lourdes enseña demasiado bien, jeta no hubiera pasado el curso si no fuera por ello, además si ve que usted le pone y esta cerca de pasar, lo ayuda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a0e93cd58e8d46e8fda35475bc7243c71134313c566662586313d753c94f57d9'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Excelente profe, explica demasiado bien y le ofrece ayuda en lo que necesite. El único aspecto negativo sería que manda muchas tareas individuales y grupales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'dfc28476898af81aec8897cb024563b6dbab57a17a98b2e99917ace354e6777a'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Es una excelente profe, explica muy bien pero explica muy rápido y en ocasiones cuesta entender el principio del tema para poder seguir el paso pero si usted pregunta ella de fijo le ayuda'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'f668981874e7ad91737f1a76cb03cd5cdfed5cc84635765ef13eab89615e5a14'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Immpresionante'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '527aec6b411795337c0e519e9b45d95961459af49bb8cdc1f8e3ac3ab6f8cf81'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Muy buena profe, las clases a veces se hacen largas pero explica muy bien y califica justo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'cdf0273872cd17a65a0a7a0cb07a9f355c3ce2a8798a6b36696b19129174e0f6'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profesora, jamás pensé que un profesor hiciera de las casas virtuales algo sencillo. Si quieren pasar e ir bien preparados para cálculo matriculen con ella.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'ab6d445c0a6a09475defdcfafc29318c73ca58ef0955f22d7f1406cdcf2dc0ca'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Lourdes es increíble, explica súper bien, es muy amable y ayuda mucho a los estudiantes. Tiene mucha paciencia para explicar cosas que incluso deberían ser conocimientos previos. Es un amor, recomiendo 100%. Se adaptó muy bien al curso virtual.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-09-09T00:00:00+00:00'::TIMESTAMPTZ, '2298a8b97fd59241f42aa3ee28aaa398594963f16c61ec56d0c3af6caf599292'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Es una profe que hace presentaciones para absolutamente todo. En la modalidad virtual es curso puede ser un poco aburrido, ya que es mas largo, pero la profe es muy clara y se preocupa de que los estudiantes entiendan bien, e incentiva a participar en clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, '4b5f692bf01456cc88be36344d541f07f52430eb605d2ab16dffc7544dd31872'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profesora, se preocupa mucho por la comprensión de los estudiantes, explica la materia cuantas veces sea necesario, siempre con ánimo de enseñar. Recomendada totalmente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'a5ae720ddeb1b6d8a1b8cb3726a789b67a5d6f1ab2e46e173bedb110f43fea6f'::TEXT, ARRAY[563, 2439]::BIGINT[]),
    (487::BIGINT, 'Es una profesora magnífica y de verdad le pone muchas ganas a la materia, se preocupa porque uno de verdad aprenda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '3fd7946383090fb6dee3d55e0f4ea75960baef131fa09cecd9c33da2a4525657'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'a44db32e99439c9e546be70a9664cdafeaff60434f891f708268fb21648bbbcf'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profe, explica y se le entiende perfectamente siempre y cuando uno haya repasado la materia con anterioridad.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '1f6e61fb02f35e62787324f43de4692801d83e2782571686e585182194ed2217'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Super buena profe, explica todo muy claro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '788f776c1ea204ed539465ee58946df1e411226f447f0678d8fecab5c2a5a497'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Super buena, recomendadisima. Una de las mejores sin duda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-26T00:00:00+00:00'::TIMESTAMPTZ, '0c73519a2a82bf060bb554249200ea6ff02768926663057ecb67bcf38759aae0'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Explica muy bien y califica con amor'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'cffa886bb110fdb020d02e1c9634efcce1718a18c6f4cd555e5cd2bdd65faa5b'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Es una profe bastante buena. Casi no deja tarea, entonces ustedes deben practicar por su cuenta. ¡Y PRACTIQUEN! Vaya siempre a clase, hace quices de la nada y un quiz le puede salvar la nota. ¡Es enserio! Cada 1% cuenta.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'ca7abc485ee5e2741353dac4028e131de5848fe7edbf6399c7270fc2eea13fc7'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profesora, proporciona un ambiente ameno, muy pura vida'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'ef6fcd39f426b914e41b76a7f52604bc88d28aa41063384ce34af2341a956ab1'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Una Excelente Profesora, es bastante clara y utiliza muchos ejemplos, sin duda matriculen con ella'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8973e4b96539474308612086b3ce8b5c81593d7ad095c21949c295a226c8b114'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Super buena persona, explica todo demasiado bien, y aclara cualquier cosa que le preguntes, es una mente. 100% recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '80e1c64bf1c678ea9460783adfba383529ee64ad41d1fad7eb3c6fad7e9f3d14'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profesora, explica muy claro, da muchos ejemplos, deja material extra por si se desea trabajar en la casa, en resumen, es de las mejores de la Escuela de Matemática, no lo dude y matricule con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '321f8666c0b512a6ed00c6feee934e4a55ed3cae12bc31bf102d593c114ebf5f'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'dcdbb0719fcf3e5d0595a86f4ea2b35216c0d76e13c8a8f8a4c2dc5911f02df4'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Una de las mejores profes de mate, demasiado buena gente. Si se queda con ella es por vago legal.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e57e1ac071d8c8ae7db919d826a8fcc2175f505eae2196adcaf7c3e51c37d01b'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profesora, explica muy bien y deja material extra por si uno quiere practicar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '5fdb4a706a7af50edd019e3412227720e24010b597db8bd320ae3484638b8168'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Es super buena nota y explica muy bien, siempre se esfuerza para hacer la materia clara y da muchos ejemplos. Muy dispuesta a ayudar a sus estudiantes. No regala puntos y califica duro pero aun asi el curso con ella es muy accesible.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '3ad4e8c4de12fe85a735cdae66a365e6ee18a94906ff6ffe9481999b50054620'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'A veces se confunde, pero muy poco, lo normal. Aunque explica bien califica más duro de lo que explica'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '013e2c9aaa3d93cb4b5e507090e571c1d2eb3b096182ce1300b83c275f1ccdbd'::TEXT, ARRAY[634]::BIGINT[]),
    (487::BIGINT, 'Explica bien la materia y atiende dudas de ser necesario, tiene que poner de su parte pues recomiendo llevar el curso al día con ella. Además hace quices bastante justos que lo deberían forzar a estudiar desde antes. Intente ser ordenado al realizar procedimiento y le irá bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2018-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'd75c267aea09443216f60eaeff2e5336cc2d6a10186a8acf62a9e03daf709138'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es muy buena profe, califica justamente pero hay que tener todo el procedimiento y no saltarse pasos ni hacerlo de una manera distinta a la que se vio en clase. Quices rudos pero ayuda a que el examen se vea fácil. Muy buena persona y la recomiendo 100 veces'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '164b7f6be37268cb24c29296af2aa31832921262114a740dce01c5fed8b98f3b'::TEXT, ARRAY[1034]::BIGINT[]),
    (487::BIGINT, 'Los quizes son un poco difíciles pero tampoco llega al extremo, explica muy claro y si no entendió ella explica las veces que sea necesario, es una persona increible, super recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '5fb5dbdaeb0b17ffc0f158b81b8ec271b3fe6cc7357660db94dd0f28f2aeb578'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Explica las veces que sea necesario para que el estudiante entienda pero no la recomiendo, es desordenada y no explica muy claro, se enreda sola en muchas ocaciones y califica duro, existen mejores profesores de la cátedra antes que ella para el curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '5cd18232db9d077d78c0a67cbc677e66accd91fee7bc48bcfd7f2213fc3126af'::TEXT, ARRAY[634]::BIGINT[]),
    (487::BIGINT, 'Muy buena profe, explica claro y maneja bien la clase. Tener cuidado al matricular con ella porque califica bastante duro, pero se aprende bastante.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'da11cd29267a63d06c842ecf6b717f75664ad573f111a55f610d200cca7a8319'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'excelente pero hay que tener demasiado cuidado porque califica duro y quices dificiles'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-10-29T00:00:00+00:00'::TIMESTAMPTZ, 'd6f2de2503701a704b529029710f162853f89acffd0d58ad6f73dd902f7d38ab'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Super recomendada, explica bastante claro, siempre ayuda las veces que sea necesario, califica justo ya que explica muy bien. Si puede matricular con ella no lo piense.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'b43750532958aedd66180f5e49bf4067aa6ba322f1f4a858beede07b23a089e1'::TEXT, ARRAY[935]::BIGINT[]),
    (487::BIGINT, 'Explica bien, califica duro. No es de las mejores opciones, pero en general está bien.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '66985ee8addd4dae56bc5cb9c1b08ff508ce07b3ce95dd52b564ec3ce0da0a81'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Le gustan las cosas bien hechas, explica genial y las veces que sea necesario. Ayuda mucho y se interesa porque los estudiantes aprendan. Super recomendada'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a7449d4ef9c7a70367003a7873e42b281285ea09792d1c739c8d3122ab1a4988'::TEXT, ARRAY[634]::BIGINT[]),
    (487::BIGINT, 'La profe es muy buena, hace ejemplos y es clara. A veces deja quices para la casa o en grupo; califica justo, pero sí le gusta que el examen esté bien explicado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '541927db898f2531192b294a9c9f97d8b85c3443b0b5fa12f06261fba39cd844'::TEXT, ARRAY[935]::BIGINT[]),
    (487::BIGINT, 'La profe explica muy bien y la mayoría de los quices son en la casa o grupales. Es de argolla, por lo que participar en clase y ojalá sentarse al frente ayuda mucho, sino probablemente le califique muy binario los exámenes. Le gusta que en los exámenes esté bien explicado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '101a5d7c56228c52f328fd4a4d94cf4d764bbc1aaec56564438a387383564aed'::TEXT, ARRAY[634]::BIGINT[]),
    (487::BIGINT, 'muy buena profe, manda quices para la casa, quices en clase grupales, califica justo si ve que usted le pone! explica claro y da muy buenos ejemplos, explica cuantas veces sea necesario, no dude en meter con ella...'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'aab1ae61c06a0bb00aac0fe71a19c269f118ef76650d5dadc56c0522e0c5b2a1'::TEXT, ARRAY[634]::BIGINT[]),
    (487::BIGINT, 'Es súper buena profe, explica hasta 10 veces si es necesario, en clase hace ejemplos tipo examen y en consulta es un amor. Recomendadísima'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-03-20T00:00:00+00:00'::TIMESTAMPTZ, '91d319065b397c6b7de1f6b5a29be7b01a7659155ddd51e0531c12c66fdc3e5a'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '916686e77b1d00798ae7e34babd8835eed5f3b91b3bbf000640d96364208287a'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es un amor de profe, explica bien, da demasiado material, en consulta es como cuando uno estudiaba con la mamá en la escuela, siempre se queda a aclarar dudas después de clases y es muy amable. Es cierto que califica rudo, pero en mi experiencia no tanto, si se nota que sabe algo le da puntos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'dc493b3b9c23c671e9da645abead0f0e1f438ed2281360721b137667a4069872'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-04T00:00:00+00:00'::TIMESTAMPTZ, '9420caa212f93953b2883a097b9b418d79abc8909202e6bf350ea12eca6160a5'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Explica masomenos, es muy desordenada, da muy pocos ejemplos, hace quices virtuales y con una aplicacion es muy raro y no favorecen a la nota, dura mucho para califica, deja tarea muy dificiles y con poco tiempo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '6e5c56ed1eaeaa44ef11430836bfd32a26631a91b86e34d41efb8fdf2ecd2ea5'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'adfa0e86acf135260a283ebf67ad5ce8a6b8cbd1a13e5eeb83fb03082d6987c1'::TEXT, ARRAY[634]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f240891b7fa1c272fa3b24910535c9025bec1c8da680fadb911149565d98dc7e'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'f0032cb1945a8fc166e2634c380453850b5beaf0de02c8fb1853e965bb37ba30'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Una teja! Explica bien y siempre esta dispuesta a ayudar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-10T00:00:00+00:00'::TIMESTAMPTZ, '47d7e3610a5bdcc3a31170cb931eeb4c4d90eed2446407ff643e2c16213dbfec'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'MUY buena profe, la gente dice que califica duro pero ella misma advierte que cosas no hacer en el examen y eso es todo. Se le entiende bien y deja muchisimo material de apoyo para el que no entienda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '9452358c70e3bccf15d3b93bf2e9e93cf36cf71e20cf9d8b54e591b63aff1af4'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Califica muy muy rudo!'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'bbab2ac1a110ca7bdf5ec220a2ce56440fc734f9ea39267d6a054a6202f8c238'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'NO LO LLEVE CON ELLA si usted no entiende y pregunta lo mismo más de una vez o tiene dudas "básicas" le va a responder de la forma más acertada para averganzarlo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, '0f378fe356ae00e91813dfcde5888c2e1d8de2a5ba178846b58e40651e90d170'::TEXT, ARRAY[1034, 605]::BIGINT[]),
    (487::BIGINT, 'Muy buena profe, amable y siempre atiende dudas. Explica rápido pero nada del otro mundo, solo estar atento. Califica durillo pero nada del otro mundo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-26T00:00:00+00:00'::TIMESTAMPTZ, '9e0ff538d555c16792047e1155cbdf757e3a108a788273ee5c43be60709de067'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd45e20154fbaf4ba75843d94a4075e8b91d1e9d452523acf0d270477bf8e9fe3'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'excelente profe, asistencia es muy importante porque hace trabajos grupales que cuentan como quices, pero califica accesiblemente y si se tiene alguna duda se toma el tiempo!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '39b73f0263310d6220852b75d13479983c6df0c79ac7848d168747b0d456309a'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'muy buena profe, se hacen muchos trabajos grupales que ayudan a subir la nota.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9bccd53003b12c86c162eedf9cd970540d4386764c66fb2dbfcf6f2cb74a8777'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'cc4eb4ae60666d0c0f5923af657e5ea2df987ae77175d2ee0f195b78ce045be2'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Excelente profesora, se comporta practicamente como una mamá, brinda mucho material como videos, prácticas y libros para que usted entienda mejor. Se preocupa por mejorar cada día y los temas se terminan con tiempo. Califica durillo en quices pero en los exámenes no (un paso mal le baja un 0.3).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '5ab9479977effa443638904ea8bdf32659512ebecb622288fc4fa5ca8386caa7'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'La ayuda en consulta es bastante buena. ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-02T00:00:00+00:00'::TIMESTAMPTZ, '0b2421721353355439afbb9df1ea851368dd67ea113eb90f565996adfdc71d81'::TEXT, ARRAY[634]::BIGINT[]),
    (487::BIGINT, 'Explica muy bien, los quices y tareas son un poco durillos, califica un toque duro, pero ella explica calidad.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'f9894642b83a9c1e804ad74ae3260ff879382899ceb2dcd3707c5bd8f1cbb0b0'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2015-07-20T00:00:00+00:00'::TIMESTAMPTZ, '81729281cbf8dccb7ba02b0dcc993697816e2c8445d3569e869a06cce8e8c6f0'::TEXT, ARRAY[634]::BIGINT[]),
    (487::BIGINT, 'Explica muy bien, ayuda mucho en consulta y califica normal'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'e7136f4213f03b71e14e2370fdf373f80398589f025d0926b9c620a5fa1c3b83'::TEXT, ARRAY[563]::BIGINT[]),
    (487::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'b13facf771e94f53a9470f5c09d5ec9f6928f62be43ac3866157332f9c0b0fc6'::TEXT, ARRAY[605]::BIGINT[]),
    (487::BIGINT, 'Es una buena profesora pero su problema es que a veces va muy rápido y se enreda ella sola. Califica muy duro (quices y exam)! Recomiendo estudiar o leer la materia antes y después de sus clases para seguirle el ritmo, sino uno se pierde. Como persona es muy agradable y simpática. Muy puntual!'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'c8e568dfd4dc2ee45098d8d9e4f347fe14f9126595d3946248c5894e40a318bd'::TEXT, ARRAY[1018]::BIGINT[]),
    (487::BIGINT, 'Buena profesora explica bien aunque a veces se emociona demasiado y explica muy rápido pero lo hace bien, da ejemplos parecidos a los de los exámenes. Califica duro hay que ganarse cada punto en los examenes.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '4dd1007e74d2169a6d5089828fb556ac9d466a41111138cd016ab0841a88b2d0'::TEXT, ARRAY[1018]::BIGINT[]),
    (487::BIGINT, 'El curso es duro, pero ella explica bien todo y da ejemplos que se parecen a los del examen. Califica duro, tiene que ganarse los puntos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'a4cf4c7cc4b3ba4a38146428ef5729488aaff0ac83c16740d4a9b088c86d21b4'::TEXT, ARRAY[1018]::BIGINT[]),
    (487::BIGINT, 'Excelente profe, da muchos ejemplos y se preocupa que el estudiante entienda. Califica duro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '7440869acb1c664f99279c2651fd7c385d4026ab643987ac4cfe2957be3f5966'::TEXT, ARRAY[1018]::BIGINT[]),
